function migrate(raw){
  if(raw?.schemaVersion===2&&window.CompassoDataV2)return window.CompassoDataV2.hydrate(raw);
  const freshInstall=!raw||!Array.isArray(raw.alunos), source = freshInstall ? structuredClone(seed) : raw;
  source.alunos = source.alunos.map((a,index)=>{
    const musics=(a.musicas||a.repertorio||[]).map(m=>typeof m==='string'?{nome:m,autor:'',status:'Aprendendo',inicio:todayISO()}:({...m,status:m.status||m.etapa||'Aprendendo'}));
    const history=a.livrosHistorico||a.livros?.map((l,i)=>typeof l==='string'?{nome:l,inicio:a.desde||todayISO(),...(i<a.livros.length-1?{fim:todayISO()}:{})}:l)||[];
    if(a.livro && !history.some(h=>norm(h.nome)===norm(a.livro))) history.push({nome:a.livro,inicio:a.desde||todayISO()});
    const aulas=a.aulas&&Array.isArray(a.aulas)?a.aulas:[{dia:a.dia||'Segunda',hora:a.hora||'10:00',duracao:a.duracao||50}];
return {...a,id:a.id??Date.now()+index,ini:a.ini||initials(a.nome),cor:a.cor||COLORS[index%COLORS.length],desde:a.desde||todayISO(),ativo:a.ativo!==false,aulas,dia:aulas[0]?.dia||a.dia||'Segunda',hora:aulas[0]?.hora||a.hora||'10:00',duracao:aulas[0]?.duracao||a.duracao||50,livrosHistorico:history,musicas:musics};
  });
  source.pagamentos=(source.pagamentos||[]).map(p=>({...p,alunoId:p.alunoId??p.aluno}));
  const bookNames=[...source.alunos.flatMap(a=>a.livrosHistorico.map(h=>h.nome)),...(source.livros||[]).map(x=>typeof x==='string'?x:x.nome)].filter(Boolean);
  const repertoireRows=[...source.alunos.flatMap(a=>a.musicas),...(source.repertorio||[])];
  source.livros=[...new Map(bookNames.map(nome=>[norm(nome),{nome,comentarios:(source.livros||[]).find(x=>norm(x.nome)===norm(nome))?.comentarios||''}])).values()];
  source.repertorio=[...new Map(repertoireRows.map(x=>{const item=typeof x==='string'?{nome:x,autor:'',comentarios:''}:x;return [norm(item.nome),{nome:item.nome,autor:item.autor||'',comentarios:item.comentarios||''}]})).values()];
  source.demoEligible=source.demoEligible===true||freshInstall;
  return source;
}

let data=migrate(JSON.parse(localStorage.getItem(STORAGE_KEY)||localStorage.getItem(OLD_STORAGE_KEY)||'null'));
data.settings=data.settings||{teacherName:'',schoolName:''};
let ui={page:'inicio',selectedStudent:null,selectedItem:null,selectedPayment:null,selectedClass:null,libraryKind:'musica',search:'',paymentFilter:'all',scheduleDay:DAYS[(new Date().getDay()+6)%7],paymentMonth:0,moneyVisible:false,agendaView:'week',agendaMonth:0};
const app=$('#app');
function toast(message){document.body.insertAdjacentHTML('beforeend',`<div class="toast">✓ ${esc(message)}</div>`);setTimeout(()=>$('.toast')?.remove(),2200)}
function photoSource(photo){return typeof photo==='string'?photo:photo?.src||''}
function avatar(a){return a.foto?`<i class="avatar photo" data-photo-view="${esc(photoSource(a.foto))}" style="${photoStyle(a.foto)}" aria-label="Abrir foto de ${esc(a.nome||'perfil')}"></i>`:`<i class="avatar" style="background:${a.cor}">${esc(a.ini)}</i>`}
function thumb(item,kind){return item?.foto?`<i class="thumb" data-photo-view="${esc(photoSource(item.foto))}" style="${photoStyle(item.foto)}" aria-label="Abrir foto"></i>`:`<i class="${kind==='livro'?'book':''}">${kind==='livro'?'▤':'♫'}</i>`}
function header(label,title,action=''){return `<header><div><small>${esc(label)}</small><h1>${esc(title)}</h1></div>${action}</header>`}
function searchBox(placeholder='Buscar por palavra-chave'){return `<label class="search">⌕<input id="page-search" value="${esc(ui.search)}" placeholder="${esc(placeholder)}"><button type="button" id="clear-search">${ui.search?'×':'⌕'}</button></label>`}

function legacyHome(){
  const today=data.alunos.filter(a=>a.dia===ui.scheduleDay).sort((a,b)=>a.hora.localeCompare(b.hora));
  return header('ESTÚDIO DE PIANO','Olá 👋','<button class="top-button" aria-label="Notificações">♧</button>')+
  `<section class="welcome"><div><small>VISÃO DO DIA</small><h2>${today.length} ${today.length===1?'aula':'aulas'} hoje</h2><p>Sua rotina musical, organizada e tranquila.</p></div><span>♫</span></section>
  <div class="summary home-summary"><button data-page="agenda"><b>▦</b><span><strong>${data.alunos.length}</strong><small>Alunos ativos na semana</small></span>›</button><button data-page="acervo"><b>♫</b><span><strong>${data.repertorio.length}</strong><small>Peças no repertório</small></span>›</button></div>
  <div class="section-title"><div><small>${esc(ui.scheduleDay.toUpperCase())}</small><h2>Próximas aulas</h2></div><button data-page="agenda">Ver agenda</button></div>
  <div class="rows">${today.length?today.map(studentRow).join(''):'<p class="empty">Nenhuma aula neste dia.</p>'}</div>`;
}
function classSlots(a){return (a.aulas&&a.aulas.length?a.aulas:[{dia:a.dia,hora:a.hora,duracao:a.duracao}]).filter(x=>x.dia&&x.hora)}
function studentRow(a,slot=classSlots(a)[0]){return `<button class="row" data-student="${a.id}"><strong class="time">${esc(slot.hora)}<small>${slot.duracao||50} min</small></strong>${avatar(a)}<span><b>${esc(a.nome)}</b><small>${esc(a.livro||'Sem livro definido')}</small></span>›</button>`}
function inactiveStudents(){const list=data.alunos.filter(a=>a.ativo===false).sort(compareNames);return header('HISTÓRICO','Alunos que não têm mais aulas','<button class="close" data-page="alunos">×</button>')+`<div class="cards">${list.length?list.map(a=>`<button class="student" data-student="${a.id}">${avatar(a)}<b>${esc(a.nome)}</b><small>Encerrado em ${esc(a.encerradoEm||'—')}</small></button>`).join(''):'<p class="empty">Nenhum aluno encerrado.</p>'}</div>`}

function secretMoney(value){return `<span class="money ${ui.moneyVisible?'revealed':''}" data-value="${esc(money(value))}"><b>${ui.moneyVisible?esc(money(value)):'••••••'}</b></span>`}
function payments(){
  const month=monthLabel(ui.paymentMonth),list=data.pagamentos.filter(p=>norm(p.ref).includes(norm(month.label.split(' ')[0]))||norm(p.ref).includes(norm(month.key))).filter(p=>ui.paymentFilter==='all'||(ui.paymentFilter==='paid'?p.pago:!p.pago));
  const total=data.pagamentos.reduce((s,p)=>s+Number(p.valor),0), paid=data.pagamentos.filter(p=>p.pago).reduce((s,p)=>s+Number(p.valor),0);
  return header('CONTROLE FINANCEIRO','Pagamentos',`<div class="header-actions"><button id="money-eye" class="eye" aria-label="Segure para mostrar valores" title="Segure para mostrar valores">◉</button><button class="add" data-modal="pagamento" aria-label="Novo pagamento">＋</button></div>`)+
  `<div class="month"><button data-month="-1">‹</button><b>${esc(month.label)}</b><button data-month="1">›</button></div><p class="hold-hint">Segure o botão de olho para visualizar os valores.</p><div class="finance"><span><small>Recebido</small>${secretMoney(paid)}</span><span><small>A receber</small>${secretMoney(total-paid)}</span></div><div class="filters">${[['all','Todos'],['paid','Recebidos'],['pending','Pendentes']].map(x=>`<button class="${ui.paymentFilter===x[0]?'active':''}" data-filter="${x[0]}">${x[1]}</button>`).join('')}</div><div class="rows payments">${list.length?list.map(p=>{const a=data.alunos.find(x=>x.id===p.alunoId);if(!a)return '';return `<div class="payment" data-payment="${p.id}"><button class="person" data-student="${a.id}">${avatar(a)}<span><b>${esc(a.nome)}</b><small>${esc(p.ref)} · ${esc(a.plano)}</small></span></button><span class="payment-actions">${secretMoney(p.valor)}${p.pago?'<small class="ok">✓ Recebido</small>':`<button class="confirm" data-pay="${p.id}">Confirmar</button>`}</span></div>`}).join(''):'<p class="empty">Nenhum pagamento registrado neste mês.</p>'}</div>`;
}

function library(){
  const source=ui.libraryKind==='livro'?data.livros:data.repertorio;
  const list=source.filter(item=>norm(`${item.nome} ${item.autor||''}`).includes(norm(ui.search))).sort(compareNames);
  const label=ui.libraryKind==='livro'?'livro':'música';
  return header('MATERIAL PEDAGÓGICO','Acervo',`<button class="add" data-modal="${label}" aria-label="Adicionar ${label}">＋</button>`)+
  `<div class="switch"><button class="${ui.libraryKind==='musica'?'active':''}" data-kind="musica">♫ Repertório</button><button class="${ui.libraryKind==='livro'?'active':''}" data-kind="livro">▤ Livros</button></div>${searchBox(`Buscar ${label}`)}<div class="library">${list.length?list.map(item=>{const users=currentUsers(ui.libraryKind,item.nome);return `<button data-item="${esc(item.nome)}">${thumb(item,ui.libraryKind)}<span><b>${esc(item.nome)}</b>${item.autor?`<small>${esc(item.autor)}</small>`:''}<em>${users.length} ${users.length===1?'aluno atual':'alunos atuais'}</em></span>›</button>`}).join(''):'<p class="empty">Nenhum item encontrado.</p>'}</div>`;
}
function currentUsers(kind,name){return data.alunos.filter(a=>kind==='livro'?norm(a.livro)===norm(name):a.musicas.some(m=>norm(m.nome)===norm(name)&&!m.fim))}
function historicUsers(kind,name){return data.alunos.filter(a=>kind==='livro'?a.livrosHistorico.some(h=>norm(h.nome)===norm(name)&&h.fim):a.musicas.some(m=>norm(m.nome)===norm(name)&&m.fim))}
function personLine(a){return `<button class="person-line" data-student="${a.id}">${avatar(a)}<span><b>${esc(a.nome)}</b><small>${esc(a.dia)}, ${esc(a.hora)}</small></span>›</button>`}


function render(){lastRenderedDate=todayISO();let body=ui.selectedClass?classDetail():ui.selectedStudent?studentProfile():ui.selectedItem?itemDetail():ui.selectedPayment?paymentDetail():ui.page==='inicio'?home():ui.page==='agenda'?schedule():ui.page==='alunos'?students():ui.page==='inativos'?inactiveStudents():ui.page==='pagamentos'?payments():library();app.innerHTML=`<main class="layout">${nav()}<section class="content">${body}</section></main>`;bind()}

function bind(){
  $$('[data-page]').forEach(el=>el.onclick=()=>{ui.page=el.dataset.page;ui.selectedStudent=null;ui.selectedItem=null;ui.selectedPayment=null;ui.selectedClass=null;ui.search='';render()});
  $$('[data-profile-settings]').forEach(el=>el.addEventListener('click',openProfileSettings));
  $$('[data-student]').forEach(el=>el.onclick=()=>{ui.selectedStudent=resolveStudentId(el.dataset.student);ui.selectedItem=null;ui.selectedClass=null;render()});
  $$('[data-day]').forEach(el=>el.onclick=()=>{ui.scheduleDay=el.dataset.day;render()});
  $$('[data-kind]').filter(el=>el.tagName==='BUTTON').forEach(el=>el.onclick=()=>{ui.libraryKind=el.dataset.kind;ui.search='';render()});
  $$('[data-item]').forEach(el=>el.onclick=()=>{ui.selectedItem={kind:el.dataset.itemKind||ui.libraryKind,name:el.dataset.item};ui.selectedStudent=null;render()});
  $('[data-close-item]')?.addEventListener('click',()=>{ui.selectedItem=null;render()});
  $('[data-close-payment]')?.addEventListener('click',()=>{ui.selectedPayment=null;render()});
  $('#page-search')?.addEventListener('input',e=>{ui.search=e.target.value;const pos=e.target.selectionStart;render();const next=$('#page-search');next?.focus();next?.setSelectionRange(pos,pos)});
  $('#clear-search')?.addEventListener('click',()=>{ui.search='';render()});
  $$('[data-filter]').forEach(el=>el.onclick=()=>{ui.paymentFilter=el.dataset.filter;render()});
  $$('[data-month]').forEach(el=>el.onclick=()=>{ui.paymentMonth+=Number(el.dataset.month);ui.moneyVisible=false;render()});
  $$('[data-payment]').forEach(el=>el.onclick=()=>{ui.selectedPayment=el.dataset.payment;render()});
  $$('[data-pay]').forEach(el=>el.onclick=e=>{e.stopPropagation();openPaymentConfirmation(el.dataset.pay)});
  $$('[data-cancel-payment]').forEach(el=>el.onclick=()=>showActionDialog({title:'Cancelar confirmação?',message:'O pagamento voltará a ficar pendente. O histórico do recebimento será preservado.',actions:[{label:'Cancelar confirmação',tone:'danger',run:()=>cancelPaymentSparse(el.dataset.cancelPayment)},{label:'Voltar',tone:'neutral'}]}));
  $$('[data-modal]').forEach(el=>el.onclick=()=>{openModal(el.dataset.modal);if(el.dataset.modal==='aluno')setTimeout(setupPlanValueLabel)});
  $$('[data-edit-student]').forEach(el=>el.onclick=()=>{openStudentModal(resolveStudentId(el.dataset.editStudent));setTimeout(setupPlanValueLabel)});
  $$('[data-stop-student]').forEach(el=>el.onclick=()=>stopStudent(resolveStudentId(el.dataset.stopStudent)));
  $$('[data-assign-book]').forEach(el=>el.onclick=()=>openAssignmentModal('livro',resolveStudentId(el.dataset.assignBook)));
  $$('[data-assign-music]').forEach(el=>el.onclick=()=>openAssignmentModal('musica',resolveStudentId(el.dataset.assignMusic)));
  $$('[data-book-history]').forEach(el=>el.onclick=()=>openBookHistoryModal(resolveStudentId(el.dataset.bookHistory)));
  $$('[data-book-status]').forEach(el=>el.onclick=()=>cycleBookStatus(resolveStudentId(el.dataset.studentId),Number(el.dataset.bookStatus)));
  $$('[data-edit-book-link][data-student-id]').forEach(el=>el.onclick=()=>openBookRelationModal(resolveStudentId(el.dataset.studentId),Number(el.dataset.editBookLink)));
  $$('[data-edit-music-link]').forEach(el=>el.onclick=()=>openMusicRelationModal(resolveStudentId(el.dataset.studentId),Number(el.dataset.editMusicLink)));
  $$('[data-toggle-goners]').forEach(el=>el.onclick=()=>{ui.showGoners=!ui.showGoners;render()});
  $$('[data-stage-student]').forEach(el=>el.onclick=()=>cycleStage(resolveStudentId(el.dataset.stageStudent),el.dataset.stageMusic));
  $$('[data-remove-music]').forEach(el=>el.onclick=()=>archiveMusic(resolveStudentId(el.dataset.studentId),el.dataset.removeMusic));
  $$('[data-student-note]').forEach(el=>el.onchange=()=>{const a=data.alunos.find(x=>x.id===resolveStudentId(el.dataset.studentNote));a.notas=el.value;if(!save())return;toast('Observações salvas')});
  $$('[data-item-note]').forEach(el=>el.onchange=()=>{const list=el.dataset.kind==='livro'?data.livros:data.repertorio;const item=list.find(x=>norm(x.nome)===norm(el.dataset.itemNote));item.comentarios=el.value;if(!save())return;toast('Comentários salvos')});
  $$('[data-class]').forEach(el=>el.onclick=()=>{ui.selectedClass=el.dataset.class;render()});
  $$('[data-class-status]').forEach(el=>el.onclick=()=>setClassStatus(el.dataset.classStatus));
  $('[data-close-class]')?.addEventListener('click',()=>{ui.selectedClass=null;render()});
  $('[data-reschedule]')?.addEventListener('click',openRescheduleModal);
  $('[data-edit-item]')?.addEventListener('click',openItemEditModal);
  $$('[data-agenda-view]').forEach(el=>el.onclick=()=>{ui.agendaView=el.dataset.agendaView;render()});
  $$('[data-agenda-month]').forEach(el=>el.onclick=()=>{ui.agendaMonth+=Number(el.dataset.agendaMonth);render()});
  $$('[data-photo-view]').forEach(el=>el.onclick=e=>{e.preventDefault();e.stopPropagation();openPhotoViewer(el.dataset.photoView)});
  $('[data-class-note]')?.addEventListener('change',e=>saveClassNoteSparse(e.target.value));
  $('[data-payment-note]')?.addEventListener('change',e=>savePaymentNoteSparse(e.target.value));
  const eye=$('#money-eye');if(eye){const show=e=>{e.preventDefault();ui.moneyVisible=true;updateMoneyDisplay()},hide=e=>{e.preventDefault();ui.moneyVisible=false;updateMoneyDisplay()};['pointerdown','touchstart','mousedown'].forEach(n=>eye.addEventListener(n,show,{passive:false}));['pointerup','pointercancel','pointerleave','touchend','mouseup','blur'].forEach(n=>eye.addEventListener(n,hide,{passive:false}));}
}
function updateMoneyDisplay(){$$('.money').forEach(el=>{el.classList.toggle('revealed',ui.moneyVisible);$('b',el).textContent=ui.moneyVisible?el.dataset.value:'••••••'})}

function field(label,id,type='text',value='',extra=''){return `<label>${esc(label)}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,id,options,value){return `<label>${esc(label)}<select id="${id}">${options.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`}
function openModal(type){if(type==='aluno')return openStudentModal();if(type==='pagamento')return openPaymentModal();return openCatalogModal(type)}

function openPaymentModal(){modalShell('Registrar pagamento',`${selectField('Aluno','f-student',data.alunos.map(a=>`${a.id}|${a.nome}`),'')}${field('Referência','f-ref','text','','placeholder="Ex.: Setembro/2026" required')}<div class="form-grid">${field('Valor','f-value','number','','min="0" step="0.01" required')}${selectField('Situação','f-paid',['Pendente','Recebido'],'Pendente')}</div>`);$('#f-student').innerHTML=data.alunos.map(a=>`<option value="${a.id}">${esc(a.nome)}</option>`).join('');$('.modal').onsubmit=e=>{e.preventDefault();data.pagamentos.push({id:Date.now(),alunoId:resolveStudentId($('#f-student').value),ref:$('#f-ref').value.trim(),valor:Number($('#f-value').value),pago:$('#f-paid').value==='Recebido'});if(!save())return;closeModal();toast('Pagamento registrado');render()}}
function autocompleteField(label,id,value,items,placeholder){return `<label class="autocomplete">${esc(label)}<input id="${id}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off" required><div class="suggestions" id="${id}-suggestions"></div></label>`}
function bindAutocomplete(id,items,onSelect=()=>{}){items=[...items].sort(compareText);const input=$(`#${id}`),box=$(`#${id}-suggestions`);const refresh=()=>{const q=norm(input.value);const matches=q?items.filter(x=>norm(x).includes(q)).slice(0,6):[];box.innerHTML=matches.map(x=>`<button type="button" data-suggestion="${esc(x)}"><b>${esc(x)}</b><small>Já cadastrado — usar este</small></button>`).join('');$$('[data-suggestion]',box).forEach(btn=>btn.onclick=()=>{input.value=btn.dataset.suggestion;box.innerHTML='';onSelect(btn.dataset.suggestion)})};input.oninput=refresh;input.onfocus=refresh}
