function openCropper(src,onSave){
  let zoom=100,x=50,y=50,start=null;
  document.body.insertAdjacentHTML('beforeend',`<div class="modal-back crop-back"><section class="modal crop-modal"><small>FOTO</small><h2>Ajustar miniatura</h2><p>Arraste a imagem para posicionar. Use o controle para aproximar.</p><div class="crop-frame"><img src="${src}" alt="Prévia da foto"></div><label>Aproximação<input class="crop-zoom" type="range" min="100" max="260" value="100"></label><div class="crop-actions"><button type="button" class="close-crop">Cancelar</button><button type="button" class="save crop-save">Usar foto</button></div></section></div>`);
  const back=$('.crop-back'),frame=$('.crop-frame',back),img=$('img',frame),slider=$('.crop-zoom',back);
  const paint=()=>{img.style.width=`${zoom}%`;img.style.left=`${x}%`;img.style.top=`${y}%`;img.style.transform='translate(-50%,-50%)'};
  slider.oninput=()=>{zoom=Number(slider.value);paint()};
  frame.onpointerdown=e=>{start={px:e.clientX,py:e.clientY,x,y};frame.setPointerCapture?.(e.pointerId)};
  frame.onpointermove=e=>{if(!start)return;x=Math.max(0,Math.min(100,start.x+(e.clientX-start.px)/2));y=Math.max(0,Math.min(100,start.y+(e.clientY-start.py)/2));paint()};
  frame.onpointerup=()=>start=null;$('.close-crop',back).onclick=()=>back.remove();$('.crop-save',back).onclick=()=>{onSave({src,zoom,x,y});back.remove()};paint();
}
