function localISO(date){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`}
function monthDate(offset=0){const now=new Date();return new Date(now.getFullYear(),now.getMonth()+offset,1)}
function monthKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`}
function monthLabel(offset=0){const date=monthDate(offset),label=date.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});return {date,label:label[0].toUpperCase()+label.slice(1),key:monthKey(date)}}
function datesForSlotInMonth(date,slot){const target=DAYS.indexOf(slot.dia)+1,out=[],last=new Date(date.getFullYear(),date.getMonth()+1,0).getDate();for(let d=1;d<=last;d++){const day=new Date(date.getFullYear(),date.getMonth(),d);if(day.getDay()===target%7)out.push(localISO(day))}return out}
function ensurePaymentsForMonth(offset=0){
  const date=monthDate(offset),key=monthKey(date),monthName=date.toLocaleDateString('pt-BR',{month:'long'}),year=date.getFullYear();
  data.alunos.filter(a=>a.ativo!==false).forEach(a=>{
    if(a.plano==='Mensal'){
      const autoKey=`${a.id}-monthly-${key}`,existing=data.pagamentos.find(p=>p.autoKey===autoKey||(!p.autoKey&&p.alunoId===a.id&&norm(p.ref).includes(norm(monthName))));
      if(existing){existing.autoKey=autoKey;existing.dueDate=existing.dueDate||`${key}-01`}else data.pagamentos.push({id:Date.now()+Math.random(),alunoId:a.id,ref:`${monthName[0].toUpperCase()+monthName.slice(1)}/${year}`,valor:a.valor,pago:false,dueDate:`${key}-01`,autoKey});
    }else classSlots(a).forEach((slot,slotIndex)=>datesForSlotInMonth(date,slot).forEach(day=>{
      const autoKey=`${a.id}-class-${day}-${slotIndex}`;if(!data.pagamentos.some(p=>p.autoKey===autoKey))data.pagamentos.push({id:Date.now()+Math.random(),alunoId:a.id,ref:`Aula ${day.split('-').reverse().slice(0,2).join('/')}`,valor:a.valor,pago:false,dueDate:day,autoKey});
    }));
  });save();
}
