function monthlyAgenda(){ensureMonthClassRecords(ui.agendaMonth);const month=monthLabel(ui.agendaMonth),records=(data.classRecords||[]).filter(r=>r.date.startsWith(month.key)).sort((a,b)=>`${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`)),birthdayDates=data.alunos.flatMap(student=>{const date=birthdayDate(student,month.date.getFullYear());if(!date)return[];const key=localISO(date);return key.startsWith(month.key)&&studentActiveOn(student,key)?[key]:[]}),groups=[...new Set([...records.map(r=>r.date),...birthdayDates])].sort();let previousWeek='';return header('HISTÓRICO DE AULAS','Agenda')+agendaSwitch()+`<div class="month"><button data-agenda-month="-1">‹</button><b>${esc(month.label)}</b><button data-agenda-month="1">›</button></div><div class="status-legend"><i class="held"></i>Realizada<i class="cancelled"></i>Cancelada<i class="missed"></i>Falta<i class="rescheduled"></i>Reagendada<i class="birthday"></i>Aniversário</div><div class="month-history">${groups.length?groups.map(date=>{const currentWeek=weekGroup(date),breakClass=previousWeek&&currentWeek!==previousWeek?'week-break':'';previousWeek=currentWeek;const dayRecords=records.filter(r=>r.date===date),dayDate=new Date(`${date}T12:00:00`),birthdays=birthdayStudentsOn(dayDate).filter(student=>!dayRecords.some(r=>r.studentId===student.id));return `<section class="${breakClass}"><div class="history-date"><b>${esc(dayDate.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}))}</b><small>${esc(DAYS[(dayDate.getDay()+6)%7])}</small></div><div>${dayRecords.map(classAgendaEntry).join('')}${birthdays.map(birthdayOnlyEntry).join('')}</div></section>`}).join(''):'<p class="empty">Nenhuma aula neste mês.</p>'}</div>`}

