// Faster optional birth date, visible book status and protected form closing (v1.1.3)
function modalShell(title,content){document.body.insertAdjacentHTML('beforeend',`<div class="modal-back"><form class="modal" data-dirty="false"><button type="button" class="modal-close" aria-label="Fechar">×</button><small>COMPASSO</small><h2>${esc(title)}</h2>${content}<button class="save" type="submit">Salvar</button></form></div>`);const modal=$('.modal'),back=$('.modal-back');const markDirty=event=>{if(!['erase-confirmation','backup-file'].includes(event.target.id))modal.dataset.dirty='true'};modal.addEventListener('input',markDirty);modal.addEventListener('change',markDirty);modal.addEventListener('submit',()=>{modal.dataset.committing='true';setTimeout(()=>{if(modal.isConnected)delete modal.dataset.committing},0)},{capture:true});$('.modal-close',modal).onclick=()=>closeModal();back.onpointerdown=e=>{if(e.target===e.currentTarget)closeModal()}}
function closeModal(force=false,afterClose){
  const back=$('.modal-back');if(!back)return true;
  const modal=$('.modal',back),dirty=modal?.dataset.dirty==='true',committing=modal?.dataset.committing==='true';
  if(!force&&dirty&&!committing){
    showActionDialog({
      title:'Salvar alterações?',message:'Você tem alterações não salvas.',
      actions:[
        {label:'Salvar',run:()=>{modal.requestSubmit();if(!back.isConnected)afterClose?.()}},
        {label:'Descartar alterações',tone:'danger',run:()=>{back.remove();afterClose?.()}}
      ]
    });
    return false;
  }
  back.remove();return true;
}
function showActionDialog({title,message,actions}){
  if(document.querySelector('.action-dialog-back'))return;
  const previousFocus=document.activeElement,underlying=document.querySelector('.modal-back');
  const previouslyInert=underlying?.inert;
  const back=document.createElement('div');
  back.className='action-dialog-back';
  back.innerHTML=`<section class="action-dialog" role="dialog" aria-modal="true" aria-labelledby="action-dialog-title" aria-describedby="action-dialog-message"><button type="button" class="action-dialog-close" aria-label="Voltar sem alterações">×</button><small>COMPASSO</small><h2 id="action-dialog-title">${esc(title)}</h2><p id="action-dialog-message">${esc(message)}</p><div class="action-dialog-actions">${actions.map((action,index)=>`<button type="button" data-dialog-action="${index}" class="action-dialog-button ${action.tone||'primary'}">${esc(action.label)}</button>`).join('')}</div></section>`;
  document.body.appendChild(back);
  if(underlying)underlying.inert=true;
  const dismiss=()=>{back.remove();if(underlying)underlying.inert=previouslyInert;previousFocus?.focus?.()};
  back.querySelector('.action-dialog-close').onclick=dismiss;
  back.onpointerdown=event=>{if(event.target===back)dismiss()};
  back.querySelectorAll('[data-dialog-action]').forEach(button=>button.onclick=()=>{const action=actions[Number(button.dataset.dialogAction)];dismiss();action.run?.()});
  back.onkeydown=event=>{
    if(event.key==='Escape'){event.preventDefault();event.stopPropagation();dismiss()}
    if(event.key==='Tab'){
      const buttons=[...back.querySelectorAll('button')],first=buttons[0],last=buttons.at(-1);
      if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}
      else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}
    }
  };
  back.querySelector('.action-dialog-close').focus();
}
function birthdayFields(value=''){const [year='',month='',day='']=value?value.split('-'):[],months=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];return `<fieldset class="birthday-picker"><legend>Data de nascimento <small>opcional</small></legend><div><label>Dia<input id="f-birth-day" type="number" inputmode="numeric" min="1" max="31" placeholder="DD" value="${esc(day)}"></label><label>Mês<select id="f-birth-month"><option value="">Mês</option>${months.map((name,index)=>`<option value="${String(index+1).padStart(2,'0')}" ${Number(month)===index+1?'selected':''}>${name}</option>`).join('')}</select></label><label>Ano<input id="f-birth-year" type="number" inputmode="numeric" min="1900" max="${new Date().getFullYear()}" placeholder="1994" value="${esc(year)}"></label></div></fieldset>`}
function readBirthday(){const day=$('#f-birth-day').value.trim(),month=$('#f-birth-month').value,year=$('#f-birth-year').value.trim();if(!day&&!month&&!year)return '';if(!day||!month||!year)return null;const numericYear=Number(year),numericMonth=Number(month),numericDay=Number(day),date=new Date(numericYear,numericMonth-1,numericDay,12);if(numericYear<1900||numericYear>new Date().getFullYear()||date.getFullYear()!==numericYear||date.getMonth()!==numericMonth-1||date.getDate()!==numericDay)return null;return `${numericYear}-${String(numericMonth).padStart(2,'0')}-${String(numericDay).padStart(2,'0')}`}
function optionalAutocompleteField(label,id,value,items,placeholder){return `<label class="autocomplete">${esc(label)} <small class="optional-label">opcional</small><input id="${id}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off"><div class="suggestions" id="${id}-suggestions"></div></label>`}
function realBookName(name){return norm(name)==='sem livro definido'?'':String(name||'').trim()}
function clearCurrentBook(student,date=todayISO()){const current=[...student.livrosHistorico].reverse().find(relation=>!relation.fim&&realBookName(relation.nome));if(current){current.fim=date;current.status='Concluído';current.statusHistorico=(current.statusHistorico||[{status:'Atual',data:current.inicio||date}]).concat({status:'Concluído',data:date})}student.livro=''}
function cleanOptionalBooks(){data.alunos.forEach(student=>{if(!realBookName(student.livro))student.livro='';student.livrosHistorico=(student.livrosHistorico||[]).filter(relation=>realBookName(relation.nome))});data.livros=(data.livros||[]).filter(book=>realBookName(book.nome))}

function applyBookStatus(student,relation,status,date){if(status==='Atual'){student.livrosHistorico.forEach(other=>{if(other!==relation&&!other.fim){other.fim=date;other.status='Concluído';other.statusHistorico=(other.statusHistorico||[{status:'Atual',data:other.inicio||date}]).concat({status:'Concluído',data:date})}});relation.fim=undefined;relation.status='Atual';student.livro=relation.nome}else{relation.fim=date;relation.status='Concluído';if(norm(student.livro)===norm(relation.nome))student.livro=student.livrosHistorico.find(other=>other!==relation&&!other.fim)?.nome||''}relation.statusHistorico=relation.statusHistorico||[{status:'Atual',data:relation.inicio||date}];if(relation.statusHistorico.at(-1)?.status!==status)relation.statusHistorico.push({status,data:date})}
function cycleBookStatus(studentId,index){const student=data.alunos.find(x=>x.id===studentId),relation=student?.livrosHistorico?.[index];if(!relation)return;const current=relation.fim?'Concluído':'Atual',next=current==='Atual'?'Concluído':'Atual';modalShell('Atualizar livro',`<p>Escolha a situação de <b>${esc(relation.nome)}</b>.</p>${selectField('Situação','f-book-stage',['Atual','Concluído'],next)}${field('Data da alteração','f-book-stage-date','date',todayISO(),'required')}`);$('.modal .save').textContent='Confirmar situação';$('.modal').onsubmit=e=>{e.preventDefault();applyBookStatus(student,relation,$('#f-book-stage').value,$('#f-book-stage-date').value||todayISO());if(!save())return;closeModal();toast('Situação do livro atualizada');render()}}
