function readScheduleSlots(){
  return $$('[data-slot-row]',$('.modal')).map(row=>({id:row.dataset.slotId||undefined,dia:$('[data-slot-day]',row).value,hora:$('[data-slot-time]',row).value,duracao:Number($('[data-slot-duration]',row).value)||50,criadoEm:row.dataset.createdAt||todayISO()}));
}
function scheduleFormChanged(){
  const form=$('.modal');if(!form?.dataset.originalSlots)return false;
  const current=readScheduleSlots().map(slot=>({id:slot.id||'',dia:slot.dia,hora:slot.hora,duracao:slot.duracao}));
  return JSON.stringify(current)!==form.dataset.originalSlots;
}
function updateScheduleEffectiveField(){
  const wrapper=$('#schedule-effective-wrap');if(wrapper)wrapper.hidden=!scheduleFormChanged();
}
function scheduleConflicts(candidate,studentId,from){
  schemaV2Engine.sync(candidate);
  const messages=new Set(),minutes=time=>Number(time.slice(0,2))*60+Number(time.slice(3)),overlap=(a,b)=>minutes(a.time)<minutes(b.time)+b.duration&&minutes(b.time)<minutes(a.time)+a.duration;
  const schedules=candidate.classSchedules,students=new Map(candidate.students.map(student=>[String(student.id),student]));
  const target=schedules.filter(slot=>String(slot.studentId)===String(studentId)&&(!slot.validTo||slot.validTo>=from));
  for(const a of target)for(const b of schedules){
    if(a.id===b.id||a.weekday!==b.weekday||!overlap(a,b))continue;
    const sa=students.get(String(a.studentId)),sb=students.get(String(b.studentId));if(!sa||!sb)continue;
    for(const pa of schemaV2Engine.enrollmentPeriods(sa))for(const pb of schemaV2Engine.enrollmentPeriods(sb)){
      const start=[from,a.validFrom,b.validFrom,pa.startDate,pb.startDate].filter(Boolean).sort().at(-1),end=[a.validTo,b.validTo,pa.endDate,pb.endDate].filter(Boolean).sort()[0]||'9999-12-31';
      const date=new Date(start+'T12:00:00'),wanted=(DAYS.indexOf(a.weekday)+1)%7;
      date.setDate(date.getDate()+(wanted-date.getDay()+7)%7);
      if(localISO(date)<=end)messages.add(`${sb.name}: ${b.weekday}, ${b.time}`);
    }
  }
  return [...messages];
}
