monthlyAgenda=function(){const month=monthLabel(ui.agendaMonth),last=localISO(new Date(month.date.getFullYear(),month.date.getMonth()+1,0)),records=projectedClassesV2(`${month.key}-01`,last),birthdayDates=data.alunos.flatMap(student=>{const date=birthdayDate(student,month.date.getFullYear());if(!date)return[];const key=localISO(date);return key.startsWith(month.key)&&studentActiveOn(student,key)?[key]:[]}),groups=[...new Set([...records.map(record=>record.date),...birthdayDates])].sort();let previousWeek='';return header('HISTÓRICO DE AULAS','Agenda')+agendaSwitch()+`<div class="month"><button data-agenda-month="-1">‹</button><b>${esc(month.label)}</b><button data-agenda-month="1">›</button></div><div class="status-legend"><i class="held"></i>Realizada<i class="cancelled"></i>Cancelada<i class="missed"></i>Falta<i class="rescheduled"></i>Reagendada</div><div class="month-history">${groups.length?groups.map(date=>{const currentWeek=weekGroup(date),breakClass=previousWeek&&currentWeek!==previousWeek?'week-break':'';previousWeek=currentWeek;const dayRecords=records.filter(record=>record.date===date),dayDate=new Date(`${date}T12:00:00`),birthdays=birthdayStudentsOn(dayDate).filter(student=>!dayRecords.some(record=>String(record.studentId)===String(student.id)));return `<section class="${breakClass}"><div class="history-date"><b>${esc(dayDate.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}))}</b><small>${esc(DAYS[(dayDate.getDay()+6)%7])}</small></div><div>${dayRecords.map(classAgendaEntry).join('')}${birthdays.map(birthdayOnlyEntry).join('')}</div></section>`}).join(''):'<p class="empty">Nenhuma aula ou aniversário neste mês.</p>'}</div>`};
classDetail=function(){const record=classByIdV2(ui.selectedClass),student=data.alunos.find(item=>String(item.id)===String(record?.studentId));if(!record||!student){ui.selectedClass=null;return schedule()}const labels={pending:'Não registrada',held:'Aula realizada',teacher_cancel:'Cancelada pelo professor',student_cancel:'Cancelada pelo aluno',no_show:'Aluno não compareceu'};return header('AULA',student.nome,'<button class="close" data-close-class>×</button>')+`<div class="profile">${avatar(student)}<span><small>${record.rescheduled?'● AULA REAGENDADA':'AULA DA SEMANA'}</small><h2>${esc(record.day)}, ${esc(record.time)}</h2><p>${record.duration||50} minutos · ${formatDateBR(record.date)}</p></span></div><section class="panel"><h3>Situação da aula</h3><div class="class-statuses">${[['held','✓','Aconteceu'],['teacher_cancel','×','Professor cancelou'],['student_cancel','×','Aluno cancelou'],['no_show','!','Não compareceu']].map(option=>`<button class="${record.status===option[0]?'active':''}" data-class-status="${option[0]}"><i>${option[1]}</i><span>${option[2]}</span></button>`).join('')}</div><p class="status-note">Atual: <b>${labels[record.status]||labels.pending}</b></p>${['teacher_cancel','student_cancel'].includes(record.status)?`<button class="save" data-reschedule>${record.rescheduledTo?'Alterar reagendamento':'Reagendar aula'}</button>`:''}</section><section class="panel"><h3>Comentário da aula</h3><textarea data-class-note placeholder="Conteúdo trabalhado, exercícios, comportamento ou lembretes...">${esc(record.notes||'')}</textarea></section><button class="person-line" data-student="${student.id}">${avatar(student)}<span><b>Abrir cadastro do aluno</b><small>Livro, repertório e observações</small></span>›</button>`};
setClassStatus=function(status){const projected=classByIdV2(ui.selectedClass);if(!projected)return;const record=persistClassSparse(projected);record.status=status;record.updatedAt=new Date().toISOString();if(!save())return;toast('Situação da aula atualizada');render()};
openRescheduleModal=function(){
  const projected=classByIdV2(ui.selectedClass);if(!projected)return;
  const originalId=projected.id,student=data.alunos.find(item=>String(item.id)===String(projected.studentId));
  const replacements=()=>data.classRecords.filter(record=>String(record.originId)===String(originalId));
  const protectedReplacement=()=>replacements().some(record=>{
    const paymentKey=projected.scheduleId?schemaV2Engine.classPaymentKey(projected.studentId,projected.scheduleId,projected.date):'';
    return record.status!=='pending'||!!record.notes||record.date<=todayISO()||record.history?.length||data.pagamentos.some(payment=>String(payment.autoKey||payment.id)===paymentKey&&hasPaymentReceipt(payment));
  });
  const explain=()=>showActionDialog({title:'Reposição com histórico',message:'Esta reposição já tem registros ou recebimento associado. Seu histórico será mantido. Abra a reposição para revisar os registros.',actions:[{label:'Voltar',tone:'neutral'}]});
  if(protectedReplacement()){explain();return}
  modalShell('Reagendar aula',`${field('Nova data','f-class-date','date',projected.rescheduledTo?.date||todayISO(),'required')}${field('Novo horário','f-class-time','time',projected.rescheduledTo?.time||projected.time,'required')}${field('Duração em minutos','f-class-duration','number',projected.duration||50,'min="10" max="240" step="5"')}`);
  $('.modal').onsubmit=event=>{
    event.preventDefault();const date=$('#f-class-date').value,time=$('#f-class-time').value,duration=Number($('#f-class-duration').value)||50;
    if(!studentActiveOn(student,date)){showDuplicate('Escolha uma data dentro do período de aulas do aluno.');return}
    if(protectedReplacement()){explain();return}
    const clashes=projectedClassesV2(date,date).filter(record=>record.id!==originalId&&!replacements().some(item=>item.id===record.id)&&!['teacher_cancel','student_cancel'].includes(record.status)).filter(record=>{
      const minutes=value=>Number(value.slice(0,2))*60+Number(value.slice(3));
      return minutes(time)<minutes(record.time)+record.duration&&minutes(record.time)<minutes(time)+duration;
    });
    const commit=()=>{
      const original=persistClassSparse(classByIdV2(originalId)||projected),id=`rescheduled:${schemaV2Engine.newId('class')}`,day=DAYS[(new Date(date+'T12:00:00').getDay()+6)%7];
      data.classRecords=data.classRecords.filter(record=>String(record.originId)!==String(originalId));
      const rescheduled={id,originId:originalId,studentId:original.studentId,date,time,duration,day,status:'pending',rescheduled:true};
      data.classRecords.push(rescheduled);original.rescheduledTo={date,time};original.updatedAt=new Date().toISOString();
      if(!save())return;
      closeModal(true);ui.selectedClass=id;toast('Aula reagendada');render();
    };
    if(clashes.length)showActionDialog({title:'Horário sobreposto',message:'Já existe uma aula nesse intervalo. Deseja manter a reposição?',actions:[{label:'Reagendar mesmo assim',run:commit},{label:'Revisar horário',tone:'neutral'}]});
    else commit();
  };
};

stopStudent=function(studentId){
  const student=data.alunos.find(item=>String(item.id)===String(studentId));if(!student)return;
  if(student.ativo===false){
    modalShell('Retomar aulas',`${field('Retomar aulas a partir de','f-resume-date','date',todayISO(),'required')}<p class="archive-copy">O período sem aulas continuará preservado no histórico.</p>`);
    $('.modal .save').textContent='Retomar aulas';
    $('.modal').onsubmit=event=>{
      event.preventDefault();const date=$('#f-resume-date').value;
      const periods=structuredClone(student.enrollmentPeriods||[{startDate:student.desde,endDate:student.encerradoEm}]);
      const last=periods.at(-1);
      if(!date||date<todayISO()||(last?.endDate&&date<=last.endDate)){showDuplicate('Escolha uma data a partir de hoje e posterior ao encerramento.');return}
      student.enrollmentPeriods=[...periods,{startDate:date,endDate:null}];
      student._scheduleEffectiveDate=date;
      student.ativo=true;delete student.encerradoEm;
      if(!save())return;
      closeModal(true);toast('Aluno reativado');render();
    };return;
  }
  modalShell('Encerrar aulas',`<div class="archive-summary">${avatar(student)}<span><b>${esc(student.nome)}</b><small>O aluno ficará em Ex-alunos.</small></span></div><p class="archive-copy">Os próximos horários serão liberados. Pagamentos recebidos e pendências até hoje serão mantidos.</p><button type="button" class="archive-cancel">Continuar aulas</button>`);
  const modal=$('.modal');modal.classList.add('archive-modal');
  $('.save',modal).textContent='Encerrar aulas';
  $('.archive-cancel',modal).onclick=()=>closeModal(true);
  modal.onsubmit=event=>{
    event.preventDefault();
    const before=structuredClone(data),end=todayISO();
    student.ativo=false;student.encerradoEm=end;
    data.classRecords=(data.classRecords||[]).filter(record=>String(record.studentId)!==String(student.id)||record.date<=end);
    data.pagamentos=(data.pagamentos||[]).filter(payment=>hasPaymentReceipt(payment)||String(payment.alunoId)!==String(student.id)||!payment.dueDate||payment.dueDate<=end);
    if(!save()){data=before;return}
    closeModal(true);toast('Aluno arquivado. Histórico de recebimentos preservado.');render();
  };
};

