home=function(){const date=todayISO(),day=DAYS[(new Date().getDay()+6)%7];ui.scheduleDay=day;const today=projectedClassesV2(date,date).map(record=>({a:data.alunos.find(student=>String(student.id)===String(record.studentId)),slot:{hora:record.time,duracao:record.duration||50}})).filter(entry=>entry.a).sort((left,right)=>left.slot.hora.localeCompare(right.slot.hora));return header('ESTÚDIO DE PIANO',data.settings?.teacherName?`Olá, ${data.settings.teacherName} 👋`:'Sua semana',`<button class="top-button profile-shortcut profile-thumbnail" data-profile-settings aria-label="Editar perfil do professor">${profileShortcutAvatar()}</button>`)+`<section class="welcome"><div><small>VISÃO DO DIA</small><h2>${today.length} ${today.length===1?'aula':'aulas'} hoje</h2><p>Sua rotina musical, organizada e tranquila.</p></div><span>♫</span></section><div class="summary home-summary"><button data-page="agenda"><b>▦</b><span><strong>${data.alunos.filter(student=>student.ativo!==false).length}</strong><small>Alunos ativos na semana</small></span>›</button><button data-page="acervo"><b>♫</b><span><strong>${data.repertorio.length}</strong><small>Peças no repertório</small></span>›</button></div><div class="section-title"><div><small>${esc(day.toUpperCase())}</small><h2>Aulas de hoje</h2></div><button data-page="agenda">Ver agenda</button></div><div class="rows">${today.length?today.map(entry=>studentRow(entry.a,entry.slot)).join(''):'<p class="empty">Nenhuma aula neste dia.</p>'}</div>`};

openAssignmentModal=function(type,studentId){const student=data.alunos.find(item=>String(item.id)===String(studentId)),isBook=type==='livro',source=isBook?data.livros:data.repertorio;if(!student)return;modalShell(isBook?'Adicionar livro':'Adicionar ao repertório',`${autocompleteField(isBook?'Livro':'Música','f-title','',source.map(item=>item.nome),'Digite para ver sugestões existentes')}${isBook?'':`<div id="f-author-wrap">${field('Compositor ou artista','f-author')}</div>`}`);let selectedExisting=false;const updateExistingSelection=()=>{if(isBook)return;const title=$('#f-title').value.trim(),item=data.repertorio.find(entry=>norm(entry.nome)===norm(title)),wrapper=$('#f-author-wrap'),author=$('#f-author');selectedExisting=!!item;if(wrapper)wrapper.hidden=selectedExisting;if(author){if(item)author.value=item.autor||'';else if(selectedExisting===false&&author.dataset.fromExisting==='true')author.value='';author.dataset.fromExisting=String(selectedExisting)}};bindAutocomplete('f-title',source.map(item=>item.nome),updateExistingSelection);$('#f-title').addEventListener('input',updateExistingSelection);$('.modal').onsubmit=event=>{event.preventDefault();const name=$('#f-title').value.trim(),date=todayISO();if(!name)return;if(isBook){if(norm(student.livro)===norm(name)){showDuplicate('Este já é o livro atual do aluno.');return}ensureBook(name);changeBook(student,name)}else{let item=data.repertorio.find(entry=>norm(entry.nome)===norm(name));if(!item){item={nome:name,autor:$('#f-author').value.trim(),comentarios:''};data.repertorio.push(item)}if(student.musicas.some(music=>norm(music.nome)===norm(name)&&!music.fim)){showDuplicate('Esta música já está no repertório atual deste aluno.');return}student.musicas.push({nome:item.nome,autor:item.autor,status:'Aprendendo',inicio:date,statusHistorico:[{status:'Aprendendo',data:date}]})}if(!save())return;closeModal();toast(isBook?'Livro adicionado':'Música adicionada');render()}};

weeklyAgenda=function(){const monday=weekStart(),sunday=new Date(monday);sunday.setDate(monday.getDate()+6);const from=localISO(monday),to=localISO(sunday),today=todayISO(),records=projectedClassesV2(from,to);const dayContent=day=>{const date=weekDateForDay(monday,day),dateKey=localISO(date),entries=records.filter(record=>record.day===day).sort((a,b)=>a.time.localeCompare(b.time)),ghosts=data.alunos.filter(student=>student.ativo!==false).flatMap(student=>classSlots(student).filter(slot=>slot.dia===day).filter(slot=>{const effectiveStart=[student.desde,slot.criadoEm].filter(Boolean).sort().at(-1);return dateKey<today&&effectiveStart&&dateKey<effectiveStart&&effectiveStart>=from&&effectiveStart<=to}).map(slot=>({student,slot}))).filter(({student,slot})=>!entries.some(record=>String(record.studentId)===String(student.id)&&record.time===slot.hora)),birthdays=birthdayStudentsOn(date).filter(student=>!entries.some(record=>String(record.studentId)===String(student.id))&&!ghosts.some(ghost=>String(ghost.student.id)===String(student.id)));return {date,entries,ghosts,birthdays}};const contents=DAYS.map(day=>({day,...dayContent(day)})),days=contents.filter((content,index)=>index<5||content.entries.length||content.ghosts.length||content.birthdays.length);return header('ROTINA E HISTÓRICO','Agenda','<button class="add" data-modal="aluno" aria-label="Novo aluno">＋</button>')+agendaSwitch()+`<div class="status-legend"><i class="held"></i>Realizada<i class="cancelled"></i>Cancelada<i class="missed"></i>Falta<i class="rescheduled"></i>Reagendada</div><div class="week-agenda">${days.map(({day,entries,ghosts,birthdays})=>{const count=entries.length;return `<section class="week-day"><div><b>${day}</b><small>${count} ${count===1?'aula':'aulas'}</small></div>${entries.map(classAgendaEntry).join('')}${ghosts.map(({student,slot})=>ghostClassEntry(student,slot,weekDateForDay(monday,day))).join('')}${birthdays.map(birthdayOnlyEntry).join('')}${!entries.length&&!ghosts.length&&!birthdays.length?'<p>—</p>':''}</section>`}).join('')}</div>`};

if(schemaV2Engine){save();render()}

function compareText(a,b){return String(a||'').localeCompare(String(b||''),'pt-BR',{sensitivity:'base',numeric:true})}
function compareNames(a,b){return compareText(a?.nome,b?.nome)}
function hasPaymentReceipt(payment){return payment.pago||!!payment.pagoEm||(payment.history||[]).some(event=>event.type==='confirmed')}
function paymentStudent(payment){
  if(!payment)return null;
  const student=data.alunos.find(item=>String(item.id)===String(payment.alunoId));
  if(student)return student;
  const name=payment.studentName||'Aluno removido';
  return {id:payment.alunoId,nome:name,ini:initials(name),cor:COLORS[0],plano:payment.kind==='per_class'?'Por aula':'Mensal',removed:true};
}
function preservePaymentHistory(target,previous){
  const records=schemaV2Engine.canonicalOnly(previous).paymentRecords.map(schemaV2Engine.runtimePayment).filter(hasPaymentReceipt);
  const retained=new Map((target.pagamentos||[]).map(payment=>[String(payment.autoKey||payment.id),payment]));
  records.forEach(payment=>retained.set(String(payment.autoKey||payment.id),payment));
  target.pagamentos=[...retained.values()];
}
